package main

import (
	"bytes"
	"encoding/json"
	"flag"
	"fmt"
	"math"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
)

type Manifest struct {
	Model      Model          `json:"model"`
	Evaluations []RawEvaluation `json:"evaluations"`
}

type Model struct {
	Name     string `json:"name"`
	Version  string `json:"version"`
	TaskType string `json:"task_type"`
}

type RawEvaluation struct {
	Split       string          `json:"split"`
	Dataset    string          `json:"dataset"`
	Predictions []RawPrediction `json:"predictions"`
}

type RawPrediction struct {
	ID            string          `json:"id"`
	Actual        json.RawMessage `json:"actual"`
	Predicted     json.RawMessage `json:"predicted"`
	Probabilities json.RawMessage `json:"probabilities"`
}

type NormManifest struct {
	Model      Model
	Evaluations []NormEvaluation
}

type NormEvaluation struct {
	Split       string
	Dataset     string
	Predictions []NormPrediction
}

type NormPrediction struct {
	ID            string
	ActualStr     string
	PredictedStr  string
	ActualNum     float64
	PredictedNum  float64
	Probabilities map[string]float64
}

type RegressionConfig struct {
	Thresholds map[string]Threshold `json:"thresholds"`
	Rules      Rules                `json:"rules"`
}

type Threshold struct {
	MinAbsoluteDelta float64 `json:"min_absolute_delta"`
	MinRelativeDelta float64 `json:"min_relative_delta"`
	Severity         string  `json:"severity"`
}

type Rules struct {
	MaxCriticalRegressions int `json:"max_critical_regressions"`
	MaxWarningRegressions  int `json:"max_warning_regressions"`
}

type EvalResult struct {
	Split           string
	Dataset         string
	Metrics         map[string]float64
	ConfusionMatrix *ConfusionMatrixReport
	PerClassMetrics map[string]PerClassMetric
	Classes         []string
}

type ConfusionMatrixReport struct {
	Classes []string `json:"classes"`
	Matrix  [][]int  `json:"matrix"`
}

type PerClassMetric struct {
	Precision float64 `json:"precision"`
	Recall    float64 `json:"recall"`
	F1        float64 `json:"f1"`
	Support   int     `json:"support"`
}

type SplitReport struct {
	Dataset         string                  `json:"dataset"`
	Metrics         map[string]float64      `json:"metrics"`
	ConfusionMatrix *ConfusionMatrixReport  `json:"confusion_matrix,omitempty"`
	PerClassMetrics map[string]PerClassMetric `json:"per_class_metrics,omitempty"`
}

type ReportJSON struct {
	Model  Model                  `json:"model"`
	Splits map[string]SplitReport `json:"splits"`
}

type ModelRef struct {
	Name    string `json:"name"`
	Version string `json:"version"`
}

type DeltaEntry struct {
	Baseline      float64  `json:"baseline"`
	Candidate     float64  `json:"candidate"`
	AbsoluteDelta float64  `json:"absolute_delta"`
	RelativeDelta *float64 `json:"relative_delta"`
}

type RegressionAnalysisEntry struct {
	Severity       string   `json:"severity"`
	RegressedSplits []string `json:"regressed_splits"`
	Verdict        string   `json:"verdict"`
}

type Overall struct {
	Verdict               string `json:"verdict"`
	CriticalRegressions   int    `json:"critical_regressions"`
	MaxCriticalRegressions int   `json:"max_critical_regressions"`
	WarningRegressions    int    `json:"warning_regressions"`
	MaxWarningRegressions int    `json:"max_warning_regressions"`
}

type ComparisonData struct {
	Baseline          ModelRef                       `json:"baseline"`
	Candidate         ModelRef                       `json:"candidate"`
	TaskType          string                         `json:"task_type"`
	SplitOrder        []string                       `json:"-"`
	MetricOrder       []string                       `json:"-"`
	Deltas            map[string]map[string]DeltaEntry `json:"deltas"`
	RegressionMetrics []string                       `json:"-"`
	RegressionAnalysis map[string]RegressionAnalysisEntry `json:"regression_analysis"`
	Overall           Overall                        `json:"overall"`
}
EOF
